import { Component, Input, Output, EventEmitter, OnChanges} from '@angular/core';
import {AfterViewInit} from 'angular2/core';
import "./d3.min.js";
declare var d3: any;
declare var Dial: any;

@Component({
    selector: 'ng-dial',
    template: '<div></div>',
})

export class DialComponent implements AfterViewInit, OnChanges {
    knobs: any;
   // @Input('value') value: number;
    @Input('innerRadius') innerRadius: number;
    outerRadius: number;
    startAngle: number;
    endAngle: number;
    @Input('minValue')minValue: number;
    @Input('maxValue')maxValue: number;
    clickable: boolean;
    @Input('id') id: string;
    animated: boolean;
    @Output() outputChange: EventEmitter<any> = new EventEmitter<any>();
    @Input('value')
    set value(newValue: number) {
        if (this.knobs && this.knobs.setValue) {
            this._value = newValue;
            let adjustedValue = (newValue - this.minValue) / ((this.maxValue - this.minValue) / 100);
            this.knobs.setValue(adjustedValue);
        }
        else {
            this._value = newValue;
        }
    }
    private _value:number
    constructor() {
        this.knobs = {};
        //this._value = 0;
        this.outerRadius = 120;
        this.innerRadius = 70;
        this.startAngle = 90;
        this.endAngle = 270;
        this.clickable = true;
        this.animated = false;
        this.minValue = 0;
        this.maxValue = 10;
    }
    
    ngAfterViewInit() {
        let newValue = (this.value - this.minValue) / ((this.maxValue - this.minValue) / 100)
        this.knobs = new Dial("#" + this.id, newValue, this.innerRadius, this.outerRadius, this.startAngle, this.endAngle, this.clickable, this.outputChange, this.maxValue, this.minValue);
        this.knobs.draw(this.animated); 
    }

    ngOnChanges(changes) {
        this.value = changes.value.currentValue;
    }

}


