import { Component, Directive, Input } from '@angular/core';
import { EDDevice } from './EDDevice';
import { DemoService } from './demo.service';
import { AfterViewInit} from 'angular2/core';
import { DialComponent } from './dial.component';
import { ChartComponent } from './chart.component';

import "./d3.min.js";
declare var d3: any;
declare var Gauge: any;



@Component({
	selector: 'bbdemo-app',
	template: require('./app.component.html'),
	providers: [DemoService],
	
	})
	

export class AppComponent implements AfterViewInit {
	edDevice: EDDevice;
	voltmeterGauge: any;
	ammeterGauge: any;

	private dialComponent = new DialComponent();

	constructor(private demoService: DemoService) {
		this.edDevice = new EDDevice();
	}
	ngAfterViewInit() {
		this.voltmeterGauge = new Gauge("voltmeter", {
			size: 400,
			label: "voltmeter",
			min: 0,
			max: 10,
			minorTicks: 5,
			name: "voltmeter"
		});
		this.ammeterGauge = new Gauge("ammeter", {
			size: 400,
			label: "ammeter",
			min: 4,
			max: 20,
			minorTicks: 5,
			name: "ammeter"
		});
		this.demoService.GetInstanceStatus().subscribe((result) => {
			this.edDevice.updateData(result.data);
			this.voltmeterGauge.redraw(this.edDevice.voltmeter);
			this.ammeterGauge.redraw(this.edDevice.ammeter);
		});
	}

	demoMode(): void {
		this.edDevice.isDemoMode = !this.edDevice.isDemoMode;
		this.demoService.SendToServer(JSON.stringify(this.edDevice));
	}
	
	voltmeterChange($event) {
		//console.log("voltmeter change event");
		this.edDevice.voltmeter = $event.value;
		this.demoService.SendToServer(JSON.stringify(this.edDevice));
	}
	ammeterChange($event) {
		//console.log("ammeter change event");
		this.edDevice.ammeter = $event.value;
		this.demoService.SendToServer(JSON.stringify(this.edDevice));
	}
	caesarChange($event) {
		//console.log("lascar change")
		this.edDevice.caesar = $event.value;
		this.demoService.SendToServer(JSON.stringify(this.edDevice));

	}
	fanChange($event) {
		//console.log("fan change")
		this.edDevice.fan = $event.value;
		this.demoService.SendToServer(JSON.stringify(this.edDevice));
	}
	
	
}


