export class EDDevice {
    voltmeter: number;
    fan: number;
    isDemoMode: boolean;

    ammeter: number;
    caesar: number;
    imagePath: string;

    temp: number;
    humidity: number;
    dial1: number;
    dial2: number;
    xSlide: number;
    ySlide: number;
    waterTemp: number;

    constructor() {
        this.voltmeter = 0;
        this.ammeter = 4;
        this.caesar = 0;
        this.fan = 0;
        this.isDemoMode = false;
        this.temp = 0;
        this.humidity = 0;
        this.dial1 = 0;
        this.dial2 = 0;
        this.xSlide = 0;
        this.ySlide = 0;
        this.waterTemp = 0;
    }

    updateData(newData: string): void {
        let result = JSON.parse(newData);
        this.voltmeter = result.voltmeter;
        this.ammeter = result.ammeter;
        this.fan = result.fan;
        this.caesar = result.caesar;
        this.isDemoMode = result.isDemoMode;
        this.temp = result.temp;
        this.humidity = result.humidity;
        this.dial1 = result.dial1;
        this.dial2 = result.dial2;
        this.xSlide = result.xSlide;
        this.ySlide = result.ySlide;
        this.waterTemp = result.waterTemp;
    }
}



