import { EDDevice } from './EDDevice';
import { Component, Input } from '@angular/core';
import { AfterViewInit } from 'angular2/core';
import { TimerObservable } from 'rxjs/observable/TimerObservable';
import {Observable} from 'rxjs/Rx';
import "./d3.min.js";
declare var d3: any;
declare var Chart: any;

@Component({
    selector: 'ng-chart',
    template: '<svg></svg>',
})
export class ChartComponent implements AfterViewInit {
    @Input('value') value: number;
    chart: any;
    @Input('name') name: string;
    @Input('scale-max') scale: number;
    @Input('history-ms') history: number;
    constructor() {
        this.chart = {};
    }
    ngAfterViewInit() {
        this.chart = new Chart(this.name, { scaleMax: this.scale, historyMs: this.history });
        this.chart.drawLineChart();
        let timer = TimerObservable.create(2000, 1000);
        timer.subscribe(t => { this.updateChart(); });
    }

    ngOnChanges(changes) {
        this.value = changes.value.currentValue;
        if (this.chart.setNewValue) {
            this.chart.setNewValue(this.value);
        }
    }

    updateChart() {
        this.chart.updateChart();
    }
}


